```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(query: ModeratedQuery) -> ConversationContext {
        let customer_query = query.query;

        // requires: len(query.question) <= 512 already holds on input.
        // ensures:  len(question) <= 512 — re-establish it defensively on output,
        // counting code points as the Python-side `len` does, truncating on a
        // char boundary so we never split a multi-byte sequence.
        let mut question = customer_query.question;
        if question.chars().count() > 512 {
            question = question.chars().take(512).collect();
        }

        // The node's entire authority: read-only lookup in 'knowledge-base'.
        let mut knowledge = crate::aap::caps::kb_read::lookup(&question);

        // ensures: present(knowledge) — the output must carry knowledge.
        // If the store returned nothing, supply a single explicit placeholder
        // entry so the list is non-empty.
        if knowledge.is_empty() {
            knowledge.push(String::from(
                "No knowledge-base entries matched this query.",
            ));
        }

        ConversationContext {
            intent: customer_query.intent,
            question,
            knowledge,
        }
    }
}

export!(Node);
